public int minimumMoves(String[] grid, int startRow, int startCol, int goalRow, int goalCol) {
    int n = grid.length;
    int[][] dist = new int[n][n];
    for (int[] row : dist) Arrays.fill(row, -1);
    int[] dr = {-1, 1, 0, 0};
    int[] dc = {0, 0, -1, 1};
    Deque<int[]> queue = new ArrayDeque<>();
    dist[startRow][startCol] = 0;
    queue.offer(new int[]{startRow, startCol});
    while (!queue.isEmpty()) {
        int[] cur = queue.poll();
        int r = cur[0], c = cur[1];
        if (r == goalRow && c == goalCol) return dist[r][c];
        for (int d = 0; d < 4; d++) {
            int nr = r + dr[d], nc = c + dc[d];
            while (nr >= 0 && nr < n && nc >= 0 && nc < n && grid[nr].charAt(nc) != 'X') {
                if (dist[nr][nc] == -1) {
                    dist[nr][nc] = dist[r][c] + 1;
                    queue.offer(new int[]{nr, nc});
                }
                nr += dr[d];          // baseline: keep walking past visited cells
                nc += dc[d];
            }
        }
    }
    return dist[goalRow][goalCol];
}

