from collections import deque

def minimum_moves(self, grid: list[str], start_row: int, start_col: int, goal_row: int, goal_col: int) -> int:
    n = len(grid)
    dist = [[-1] * n for _ in range(n)]
    dist[start_row][start_col] = 0
    queue = deque([(start_row, start_col)])
    while queue:
        r, c = queue.popleft()
        if (r, c) == (goal_row, goal_col):
            return dist[r][c]
        d = dist[r][c]
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            nr, nc = r + dr, c + dc
            while 0 <= nr < n and 0 <= nc < n and grid[nr][nc] != 'X':
                if dist[nr][nc] == -1:
                    dist[nr][nc] = d + 1
                    queue.append((nr, nc))
                elif dist[nr][nc] <= d:
                    break            # earlier/equal level already sweeps the rest
                # dist == d + 1: keep walking, do not reassign
                nr += dr
                nc += dc
    return dist[goal_row][goal_col]
